#!/usr/bin/env bash
# Post-processes a Vite build of the source repo so it is safe to host under
#   ${PAGES_BASE}/pr/<slug>/   on the SAME origin as the shared Preview and production.
# usage: patch-build.sh <dist-dir> <slug>
# Every edit is asserted; a source change that breaks an assumption fails the build instead
# of silently shipping a page that shares state with (or points at) another deployment.
set -euo pipefail
source "$(dirname "$0")/lib.sh"

dist="${1:?dist dir}"; slug="${2:?slug}"
valid_slug "$slug" || die "bad slug"
[[ -f "$dist/index.html" && -f "$dist/manifest.webmanifest" ]] || die "dist is missing index.html / manifest.webmanifest"
base="${PAGES_BASE}/${PR_PAGES_DIR}/${slug}/"

# 1) PWA manifest: start_url/scope are static public/ files that Vite's base does not rewrite.
for k in start_url scope; do
  grep -q "\"$k\": \"/teto-pizza-game/\"" "$dist/manifest.webmanifest" || die "manifest $k no longer '/teto-pizza-game/'; update patch-build.sh"
  sed -i "s#\"$k\": \"/teto-pizza-game/\"#\"$k\": \"$base\"#" "$dist/manifest.webmanifest"
  grep -qF "\"$k\": \"$base\"" "$dist/manifest.webmanifest" || die "manifest $k not patched"
done

# 2) Keep the page out of search engines.
grep -q '<meta charset="UTF-8" />' "$dist/index.html" || die "index.html charset meta not found"
sed -i 's#<meta charset="UTF-8" />#<meta charset="UTF-8" />\n    <meta name="robots" content="noindex, nofollow" />#' "$dist/index.html"
grep -q 'name="robots" content="noindex, nofollow"' "$dist/index.html" || die "noindex not added"

# 2b) Browser-enforced network lockdown. The CSP <meta> is inserted as the FIRST element of the real <head> start tag, found with an HTML PARSER (python's html.parser:
#     comments, <script>/<style> text and attribute values are never mistaken for tags -- Codex P2 on PR #2, round 4), and the build FAILS if anything that can load or run
#     content (script, link, style, img, iframe, object, embed, media, base, form, svg, input, a refresh meta) starts before it. The patched document is parsed AGAIN and must
#     show the CSP meta as the first start tag after <head>, with nothing risky ahead of it; the charset must stay within the first 1024 bytes. An index.html with no explicit
#     <head> start tag (an implicit head) is refused: the policy cannot be placed first in a head the author did not write. (Limit: this is html.parser's reading of the page, not a
#     browser's; the real page is also checked in a real browser by tests/pr-page-runtime.mjs.)
if grep -q 'Content-Security-Policy' "$dist/index.html"; then die "index.html already carries a CSP; review patch-build.sh"; fi
python3 -I - "$dist/index.html" "$PR_PAGE_CSP" <<'PY' || die "could not place the CSP safely at the start of <head> (see above)"
import re, sys
from html.parser import HTMLParser

path, csp = sys.argv[1], sys.argv[2]
html = open(path, encoding="utf-8").read()
RISKY = {"script", "link", "style", "img", "iframe", "frame", "object", "embed", "video", "audio", "source", "track", "base", "form", "svg", "input"}


def fail(msg):
    print(f"::error::{msg}", file=sys.stderr)
    sys.exit(1)


class Scan(HTMLParser):
    """Records every START TAG (name, attrs, absolute offset, end offset) in document order; comments / raw text are not tags."""

    def __init__(self, text):
        super().__init__(convert_charrefs=False)
        self.text = text
        self.starts = [0]
        for m in re.finditer("\n", text):
            self.starts.append(m.end())
        self.tags = []

    def handle_starttag(self, tag, attrs):
        line, col = self.getpos()
        at = self.starts[line - 1] + col
        raw = self.get_starttag_text() or ""
        self.tags.append((tag.lower(), dict((k.lower(), v) for k, v in attrs), at, at + len(raw)))

    handle_startendtag = handle_starttag

    def handle_data(self, data):
        # text directly inside a <script> element (html.parser treats script / style bodies as raw data) = inline script
        if self.tags and self.tags[-1][0] == "script" and data.strip():
            self.inline_script = True

    inline_script = False


def scan(text):
    sc = Scan(text)
    sc.feed(text)
    sc.close()
    if sc.inline_script:
        fail("a <script> element in index.html has inline content: refused")
    return sc.tags


def risky(tag, attrs):
    return tag in RISKY or (tag == "meta" and "refresh" in (attrs.get("http-equiv") or "").lower())


# 0) FAIL CLOSED on anything where a browser and html.parser can read the page differently (Codex P2 on PR #2, round 5: "<!-->" closes a comment at once in a browser,
#    html.parser keeps it open and hides the next <script>). index.html is generated by Vite, so it needs none of it: no comment, no CDATA / bogus comment / processing
#    instruction (any "<!" other than the leading doctype, any "<?"), no inline script, and only the handful of tags a Vite shell uses. A change of the shell that needs more
#    stops the build here, to be reviewed, instead of being parsed by a tool that may disagree with the browser.
if re.search(r"<!(?!doctype\b)", html, flags=re.I) or "<?" in html:
    fail("index.html contains a comment, CDATA or processing instruction (any '<!' besides the doctype, or '<?'): refused, a browser and the HTML parser here can disagree about it")
if "\x00" in html:
    fail("index.html contains a NUL character")
ALLOWED_TAGS = {"html", "head", "meta", "link", "title", "script", "body", "div"}
tags = scan(html)
odd = [t[0] for t in tags if t[0] not in ALLOWED_TAGS]
if odd:
    fail(f"index.html uses <{odd[0]}>, outside the tags of a Vite shell ({', '.join(sorted(ALLOWED_TAGS))}): refused")
if any(t[0] == "script" and not t[1].get("src") for t in tags):
    fail("index.html contains an inline <script> (no src): refused")
heads = [t for t in tags if t[0] == "head"]
if len(heads) != 1:
    fail(f"expected exactly one explicit <head> start tag, found {len(heads)} (comments and raw text are not counted)")
head_at, head_end = heads[0][2], heads[0][3]
# STRUCTURE (Codex P2, round 6): a browser builds the head IMPLICITLY as soon as anything but <html> / whitespace / the doctype / a comment comes first, and then IGNORES a later explicit
# <head>, which would leave the CSP meta in the body where it has no effect. So the document must be: [doctype] [<html>] <head> ... with nothing else before the <head> tag.
names = [t[0] for t in tags]
if names.count("html") > 1:
    fail("index.html has more than one <html> start tag")
lead = 1 if names and names[0] == "html" else 0
if len(names) <= lead or names[lead] != "head":
    fail(f"index.html must start with [<html>] <head>, but <{names[lead] if len(names) > lead else '(nothing)'}> comes first: a browser would build the head implicitly and ignore the later <head>")
# LEXICAL check of everything in front of the <head> tag (no parser callback is trusted here: character references like &#65; / &nbsp; never reach handle_data, and Python's
# str.strip() treats U+00A0, U+0085, ... as whitespace while HTML does not -- Codex P2, round 7): remove the leading doctype and the <html> start tag; what is left must be made
# only of the five HTML whitespace characters (space, tab, LF, FF, CR). A BOM, a character reference, an NBSP, a stray word or any other tag fails.
prefix = html[:head_at]
if tags and tags[0][0] == "html":
    prefix = prefix[: tags[0][2]] + prefix[tags[0][3]:]
prefix = re.sub(r"^[ \t\n\f\r]*<!doctype\b[^>]*>", "", prefix, count=1, flags=re.I)
if prefix.strip(" \t\n\f\r") != "":
    fail("index.html has something other than the doctype, <html> and HTML whitespace before <head> (text, a character reference, a BOM or an NBSP): a browser would build the head implicitly and ignore the later <head>")
ahead = [t for t in tags if t[2] < head_at and risky(t[0], t[1])]
if ahead:
    fail(f"executable / loading content (<{ahead[0][0]}>) starts before <head>, i.e. before the CSP can apply")
meta = f'\n    <meta http-equiv="Content-Security-Policy" content="{csp}" />'
patched = html[:head_end] + meta + html[head_end:]
# verify with a second parse of the PATCHED document
ptags = scan(patched)
ph = [t for t in ptags if t[0] == "head"]
if len(ph) != 1:
    fail("after patching, the document no longer has exactly one <head> start tag")
after = [t for t in ptags if t[2] >= ph[0][3]]
first = after[0] if after else None
if not first or first[0] != "meta" or first[1].get("http-equiv", "").lower() != "content-security-policy" or first[1].get("content") != csp:
    fail("after patching, the CSP meta is not the first element of the real <head>")
if any(t[2] < first[2] and risky(t[0], t[1]) for t in ptags):
    fail("after patching, loading / executable content still precedes the CSP")
if any(t[2] < first[2] and t[0] not in ("html", "head") for t in ptags):
    fail("after patching, something other than <html> / <head> still precedes the CSP meta")
cs = re.search(r"<meta\s+charset\s*=", patched, flags=re.I)
if not cs or cs.start() > 1024:
    fail("the charset declaration is missing or beyond the first 1024 bytes after inserting the CSP")
open(path, "w", encoding="utf-8").write(patched)
PY
grep -q 'http-equiv="Content-Security-Policy"' "$dist/index.html" || die "CSP not added"

# 2c) Only inert file types, and exactly ONE HTML document (the CSP above lives in index.html only). Any other same-origin HTML / SVG / XML
#     document would be framed or navigated to WITHOUT that policy, and a Worker / Service Worker is not governed by it either: so the bundle may not
#     contain another document type, nor code that creates or registers a worker. Fail-closed: an unknown file type stops the build (add it here after review).
python3 -I - "$dist" <<'PY' || die "dist contains a file type or a worker that the page policy cannot cover (see above)"
import pathlib, re, sys
dist = pathlib.Path(sys.argv[1])
ALLOWED = {".js", ".mjs", ".css", ".png", ".webp", ".jpg", ".jpeg", ".gif", ".ico", ".json", ".woff", ".woff2", ".ttf", ".webmanifest"}
WORKER = re.compile(r"new\s+(?:Shared)?Worker\s*\(|serviceWorker\s*\.\s*register\s*\(|importScripts\s*\(")
bad = []
for f in sorted(p for p in dist.rglob("*") if p.is_file()):
    rel = f.relative_to(dist).as_posix()
    if rel == "index.html":
        continue
    if f.suffix.lower() not in ALLOWED:
        bad.append(f"{rel}: file type {f.suffix or '(none)'} is not allowed (another HTML/SVG/XML document would run without the CSP)")
        continue
    if f.suffix.lower() in {".js", ".mjs"}:
        m = WORKER.search(f.read_text(encoding="utf-8", errors="replace"))
        if m:
            bad.append(f"{rel}: creates or registers a worker ({m.group(0).strip()})")
if bad:
    print("\n".join("::error::" + b for b in bad[:10]), file=sys.stderr)
    sys.exit(1)
PY

# 2d) index.html itself may not embed another context or rebase its URLs: no frame / object / embed / base / form element (belt and braces next to the CSP).
if grep -qiE '<(iframe|frame|frameset|object|embed|base|form)[ >/]' "$dist/index.html"; then die "index.html embeds a frame / object / embed / base / form element"; fi

# 3) Separate localStorage. All of github.io shares ONE origin, so the shared Preview, production and this
#    page would otherwise share every key. Each storage key is a string literal in the bundle; the script
#    renames EVERY teto-/teto. literal to "<key>--<slug>" and FAILS on a literal it does not know, so a key
#    the app adds later can never be silently shared (see patch-storage-keys.py for the known set).
python3 -I "$(dirname "$0")/patch-storage-keys.py" "$dist" "$slug"

# 4) Path hygiene: nothing may point at the production base or the shared Preview root.
if grep -rqF '/teto-pizza-game/' "$dist"; then die "build still references the production base '/teto-pizza-game/'"; fi
stray="$(grep -rhoE "${PAGES_BASE}/[A-Za-z0-9._/-]*" "$dist" | grep -v "^${base}" | grep -vxF "${base%/}" || true)"
[[ -z "$stray" ]] || die "build references paths outside ${base}: $(echo "$stray" | sort -u | head -5 | tr '\n' ' ')"

# 5) No Firebase web config may be baked in (the build job gets no secrets; this proves it).
if grep -rqE 'AIza[0-9A-Za-z_-]{35}' "$dist"; then die "a Firebase-style API key is present in the bundle"; fi
# 6) Nothing hidden (dotfiles / dot-directories) may ship in a page.
if find "$dist" -name '.*' -print -quit | grep -q .; then die "dist contains dotfiles"; fi

echo "patched ${dist}: base=${base} storage keys suffixed with --${slug}"
